<?php
require __DIR__.'/includes/access.php';$user=require_user();$pdo=db();
$q=$pdo->prepare("SELECT r.*,u.name,u.email FROM hr_records r JOIN users u ON u.id=r.employee_id WHERE r.id=? AND r.module='payroll' AND r.status='Published'");$q->execute([(int)($_GET['id']??0)]);$r=$q->fetch(PDO::FETCH_ASSOC);
if(!$r||($user['role']!=='super_admin'&&(int)$r['employee_id']!==(int)$user['id'])){http_response_code(404);exit('Payslip unavailable.');}
$d=json_decode($r['data'],true);$earnings=['basic'=>'Basic','hra'=>'HRA','other'=>'Other earnings','overtime'=>'Overtime','incentive'=>'Incentives'];$deductions=['deductions'=>'Statutory / other deductions','lwp'=>'Attendance / LWP','advance'=>'Advance recovery'];$net=0;
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Payslip <?=h($d['month'])?></title><style>body{font:16px Arial;color:#102329;max-width:760px;margin:40px auto;padding:24px}h1{border-bottom:3px solid #b8ef42;padding-bottom:20px}table{width:100%;border-collapse:collapse}td,th{padding:15px;text-align:left;border-bottom:1px solid #ddd}td:last-child{text-align:right}.net{background:#ecffd0}button{padding:12px;cursor:pointer}@media print{button{display:none}body{margin:0}}</style></head><body><button onclick="window.print()">Print / Save as PDF</button><h1>Arkentech Solutions · Salary slip</h1><p><?=h($r['name'])?> · <?=h($d['month'])?></p><table><tbody><?php foreach($earnings as $k=>$label):$net+=(float)$d[$k];?><tr><td><?=h($label)?></td><td>₹<?=number_format((float)$d[$k],2)?></td></tr><?php endforeach;foreach($deductions as $k=>$label):$net-=(float)$d[$k];?><tr><td><?=h($label)?></td><td>− ₹<?=number_format((float)$d[$k],2)?></td></tr><?php endforeach?><tr class="net"><th>Net payable</th><td><b>₹<?=number_format($net,2)?></b></td></tr></tbody></table><p><?=nl2br(h($d['notes']))?></p><small>Published payroll record #<?=(int)$r['id']?></small></body></html>
